{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Tamoxifen, a lipophilic basic drug with a dimethylaminoethoxy side chain, has reported human oral bioavailability of 25-100%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Apixaban, which shares a methoxyphenyl and amide/lactam framework with the query, has absolute oral bioavailability of 50% in humans, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Encainide, a methoxy-substituted aromatic amide with a basic amine, showed absolute oral bioavailability of 32 ± 7% in normal subjects, above 20% despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Midodrine, a methoxyphenyl-containing drug, showed 93% absolute oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Pentopril, an ester prodrug with amide and aromatic groups, was 60-70% bioavailable in normal subjects, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to oral bioavailability at or above 20%, with most values substantially higher (32-100%). The query's structural features are consistent with these high-bioavailability drugs, and no affirmative evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the provided evidence.",
    "Some records are not explicitly absolute bioavailability or lack comparator details, adding minor uncertainty.",
    "Encainide shows a wide interindividual range (7-82%), so low-F outliers exist, but central estimates are above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

